fn is_valid_date(date: (u16, u8, u8)) -> bool {
    let (y, m, d) = date;
    if y < 1 || y > 9999 {
        return false;
    }
    if m < 1 || m > 12 {
        return false;
    }
    let days_in_month = days_in_month(y, m);
    if d < 1 || d > days_in_month {
        return false;
    }
    true
}

fn days_in_month(y: u16, m: u8) -> u8 {
    match m {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 => {
            if is_leap_year(y) {
                29
            } else {
                28
            }
        }
        _ => 0,
    }
}

fn is_leap_year(y: u16) -> bool {
    if y % 4 != 0 {
        return false;
    }
    if y % 100 != 0 {
        return true;
    }
    y % 400 == 0
}

fn next_day(date: (u16, u8, u8)) -> (u16, u8, u8) {
    let (y, m, d) = date;
    let days_in_month = days_in_month(y, m);
    if d < days_in_month {
        (y, m, d + 1)
    } else {
        if m < 12 {
            (y, m + 1, 1)
        } else {
            (y + 1, 1, 1)
        }
    }
}
